  /* Semantic */
  --color-interactive: var(--blue-500);
  /* Component */
  --btn-bg: var(--color-interactive);
}

.btn {
  /* Öffentliche API */
  --btn-bg: var(--color-primary);
  --btn-color: white;
  --btn-radius: var(--radius-md);

  background: var(--btn-bg);
  color: var(--btn-color);
  border-radius: var(--btn-radius);
  padding: var(--space-2) var(--space-4);
  border: ___;
  cursor: pointer;
}

/* Button Varianten */
.btn--primary { --btn-bg: var(--color-primary); }
.btn--secondary { --btn-bg: transparent; --btn-color: var(--color-primary); }
.btn--danger { --btn-bg: var(--color-danger); }

/* Vollständiger Button mit A11y */
.btn {
  /* Styles... */
}
.btn:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}
.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Responsive Component */
.card {
  container-type: inline-size;
}
@container (min-width: 400px) {
  .card__content {
    flex-direction: row;
  }
}
